   395  void Udp::HandlePayload(Message &aMessage, MessageInfo &aMessageInfo)
   396  {
   397      // find socket
   398      for (UdpSocket *socket = mSockets; socket; socket = socket->GetNext())
   399      {
   400          if (socket->GetSockName().mPort != aMessageInfo.GetSockPort())
   401          {
   402              continue;
   403          }
   404
   405          if (socket->GetSockName().mScopeId != 0 && socket->GetSockName().mScopeId != aMessageInfo.mInterfaceId)
   406          {
   407              continue;
   408          }
   409
   410          if (!aMessageInfo.GetSockAddr().IsMulticast() && !socket->GetSockName().GetAddress().IsUnspecified() &&
   411              socket->GetSockName().GetAddress() != aMessageInfo.GetSockAddr())
   412          {
   413              continue;
   414          }
   415
   416          // verify source if connected socket
   417          if (socket->GetPeerName().mPort != 0)
   418          {
   419              if (socket->GetPeerName().mPort != aMessageInfo.GetPeerPort())
   420              {
   421                  continue;
   422              }
   423
   424              if (!socket->GetPeerName().GetAddress().IsUnspecified() &&
   425                  socket->GetPeerName().GetAddress() != aMessageInfo.GetPeerAddr())
   426              {
   427                  continue;
   428              }
   429          }
   430
   431          aMessage.RemoveHeader(aMessage.GetOffset());
   432          assert(aMessage.GetOffset() == 0);
   433          socket->HandleUdpReceive(aMessage, aMessageInfo);
   434          break;
   435      }
   436  }
