   443      {
   444          aChecksum = ~aChecksum;
   445      }
   446
   447      aChecksum = HostSwap16(aChecksum);
   448      aMessage.Write(aMessage.GetOffset() + UdpHeader::GetChecksumOffset(), sizeof(aChecksum), &aChecksum);
