/**
 * @file
 *   This file provides an implementation of software random number generator.
 */

#include "random.hpp"

#include "debug.hpp"
#include "entropy.hpp"

namespace ot {
namespace Random {
namespace NonCrypto {

static uint32_t sState;
static bool     sSeeded;

uint32_t GetUint32(void)
{
    uint32_t mlcg, p, q;
    uint64_t tmpstate;

    assert(sSeeded);

    tmpstate = (uint64_t)33614 * (uint64_t)sState;
    q        = tmpstate & 0xffffffff;
    q        = q >> 1;
    p        = tmpstate >> 32;
    mlcg     = p + q;

    if (mlcg & 0x80000000)
    {
        mlcg &= 0x7fffffff;
        mlcg++;
    }

    sState = mlcg;

    return mlcg;
}

void Seed(uint32_t aSeed)
{
    sSeeded = true;
    sState  = aSeed;
}

} // namespace NonCrypto
} // namespace Random
} // namespace ot

